{
  "components": [
    {
      "type": "claim",
      "quote": "The 'Bioenergy' research programme supports innovative and relevant themes for Switzerland in the production of energy from biomass.",
      "gist": "The Bioenergy programme supports Swiss biomass energy innovation."
    },
    {
      "type": "claim",
      "quote": "The programme coordinates application-oriented research at the national level, exploits synergies and secures international networking.",
      "gist": "The programme coordinates national research, synergies, and international networking."
    },
    {
      "type": "claim",
      "quote": "Central questions for the future concern which biomass proportions are used with which technologies and for which products in order to make a substantial contribution to the Swiss energy system while achieving a high level of efficiency.",
      "gist": "Future research focuses on optimal biomass use, technologies, and products for efficient Swiss energy contribution."
    },
    {
      "type": "claim",
      "quote": "The system concept is becoming increasingly relevant, for example in relation to energy-storage issues, interaction with other energy technologies and bioeconomy concepts.",
      "gist": "System concepts are increasingly important for energy storage, cross-technology interaction, and bioeconomy."
    }
  ]
}
